#!/usr/bin/env bash
# unityHPC/eval_job.sh (llms-agents) — generated by /unity-hpc:connect. Do not hand-edit.
# Start the vLLM OpenAI server on the consolidated checkpoint, then lm-eval or
# the project argv. The parent job id arrives as #SBATCH --dependency=afterok.
# UNITY_SCAFFOLD_VERSION=@@UNITY_HPC_VERSION@@
set -euo pipefail

REMOTE_DIR="${REMOTE_DIR/#\~/$HOME}"
cd "$REMOTE_DIR"
APP="${REMOTE_DIR}/unityHPC"

export RESULTS_DIR="${REMOTE_RESULTS_DIR:-${REMOTE_DIR}/_results}/${CAMPAIGN}"
export PYTHONUNBUFFERED=1
export OMP_NUM_THREADS="${SLURM_CPUS_PER_TASK:-1}"
if [ -n "${HF_HOME:-}" ]; then
    export HF_HOME
fi
export LLMS_CHECKPOINT_DIR="${LLMS_CHECKPOINT_DIR:-${RESULTS_DIR}/checkpoint-final}"
# Eval reads the consolidated Hugging Face directory, not shard directories.
export LLMS_EVAL_KIND="${LLMS_EVAL_KIND:-lm-eval}"
export LLMS_ENGINE="${LLMS_ENGINE:-openai}"

set +u
[[ -f /usr/share/lmod/lmod/init/bash ]] && . /usr/share/lmod/lmod/init/bash
set -u
if [ -n "${MODULES:-}" ]; then
    module purge && module load ${MODULES}
fi

if [ -f "unityHPC/bootstrap.sh" ]; then
    exec 9>"${REMOTE_DIR}/.unity_bootstrap.lock"
    flock 9
    if [ -f "unityHPC/bootstrap.sh" ]; then
        . "unityHPC/bootstrap.sh"
    fi
    flock -u 9
    exec 9>&-
else
    if [ -n "${VENV_PATH:-}" ] && [ -f "${VENV_PATH}/bin/activate" ]; then
        . "${VENV_PATH}/bin/activate"
    fi
fi

TP="${SLURM_GPUS_ON_NODE:-${SLURM_GPUS:-1}}"
PORT="${LLMS_EVAL_PORT:-8000}"
SERVER_PID=""

stop_server() {
    if [ -n "$SERVER_PID" ]; then
        kill "$SERVER_PID" 2>/dev/null || true
        wait "$SERVER_PID" 2>/dev/null || true
    fi
}
trap stop_server EXIT

# engine=openai is the train-lane default. engine=project skips the server
# and runs the project argv, which starts in-process vLLM itself.
if [ "$LLMS_ENGINE" = "openai" ]; then
    python -m vllm.entrypoints.openai.api_server \
        --model "$LLMS_CHECKPOINT_DIR" \
        --port "$PORT" \
        --tensor-parallel-size "$TP" &
    SERVER_PID=$!
    python3 - "$PORT" <<'PY'
import socket, sys, time
port = int(sys.argv[1])
for _ in range(300):
    try:
        with socket.create_connection(("127.0.0.1", port), 1):
            raise SystemExit(0)
    except OSError:
        time.sleep(2)
sys.stderr.write("vLLM OpenAI server did not open the port\n")
raise SystemExit(1)
PY
fi

mkdir -p "$RESULTS_DIR"
if [ "$LLMS_EVAL_KIND" = "lm-eval" ]; then
    lm_eval --model local-completions \
        --model_args "model=${LLMS_CHECKPOINT_DIR},base_url=http://127.0.0.1:${PORT}/v1,tokenized_requests=False" \
        --tasks "${LLMS_EVAL_TASKS:?LLMS_EVAL_TASKS is empty}" \
        --output_path "${RESULTS_DIR}/harness" \
        --batch_size 1
    harness_json="$(find "${RESULTS_DIR}/harness" -name '*.json' -type f | head -1 || true)"
    if [ -n "$harness_json" ] && [ "$harness_json" != "${RESULTS_DIR}/harness.json" ]; then
        cp -- "$harness_json" "${RESULTS_DIR}/harness.json"
    fi
else
    # Project grader. Records are not lm-eval task rows.
    if [ -z "${LLMS_PROJECT_EVAL_ARGV:-}" ]; then
        echo "eval_job: LLMS_EVAL_KIND=project and LLMS_PROJECT_EVAL_ARGV is empty" >&2
        exit 2
    fi
    eval "$LLMS_PROJECT_EVAL_ARGV"
fi

python3 "$APP/workflow.py" write-metrics \
    --results "$RESULTS_DIR" \
    --keys "${LLMS_METRIC_KEYS:-accuracy}"
echo "=== eval done $(date -u +%Y-%m-%dT%H:%M:%SZ) kind=${LLMS_EVAL_KIND} ==="
